<script lang="ts">import {createComboboxController} from "@weiui/core";import {normalizeSvelteProps} from "./internal.js";type Item={value:string;label?:string;disabled?:boolean};let {items=[],value=$bindable(""),inputValue=$bindable(""),placeholder="",id="wui-combobox"}=$props<{items?:Item[];value?:string;inputValue?:string;placeholder?:string;id?:string}>();const controller=createComboboxController({id,defaultValue:value,defaultInputValue:inputValue,onValueChange:next=>value=next,onInputValueChange:next=>inputValue=next});controller.setItems(items);let state=$state(controller.getState());$effect(()=>{const off=controller.subscribe(next=>state=next);return off});$effect(()=>{controller.setItems(items);if(value!==state.value)controller.store.setState({...controller.getState(),value});if(inputValue!==state.inputValue)controller.store.setState({...controller.getState(),inputValue})});function p(kind:"root"|"input"|"content"|"item",index=0){state;return normalizeSvelteProps(kind==="root"?controller.getRootProps():kind==="input"?controller.getInputProps():kind==="content"?controller.getContentProps():controller.getItemProps(index))}</script><div {...p("root")} class="wui-combobox"><input {...p("input")} class="wui-combobox__input" {placeholder} value={state.inputValue} oninput={(event)=>controller.setInputValue(event.currentTarget.value)} /><div {...p("content")} class="wui-combobox__content">{#each items as item,index (item.value)}<div {...p("item",index)} class="wui-combobox__item">{item.label??item.value}</div>{/each}</div></div>
